 ('Qualification and transformation', ['qualification','transformation']),
 ('Natural phrases and references', ['expression-collocations','expression-reference']),
 ('Paragraph focus and support', ['expression-topic','expression-support']),
 ('Cohesion and sequence', ['expression-cohesion','expression-sequence']),
