def extend(lessons, add):
    for id,title,level,rule,example,prompt,choices,feedback,task,review in NEW:
        add('sentence',id,title,level,rule,example,prompt,choices[0],choices[1:],feedback[0],task,wrong_feedback=feedback[1:])
        minimum=re.search(r'at least (\d+) words',task)
        lessons[-1]['practice_min_words']=int(minimum.group(1)) if minimum else 20
        lessons[-1].update(writing_kind='paragraph' if id not in ['expression-collocations','expression-reference','expression-paraphrase'] else 'sentence',self_review=review)
    ordered=[id for _,ids in CHAPTERS for id in ids]
    for i,id in enumerate(ordered[:-1]):
        lesson=next(x for x in lessons if x['id']==id)
        lesson['next_lesson']=ordered[i+1]
    for number,(title,ids) in enumerate(CHAPTERS,1):
        for order,id in enumerate(ids,1):
            lesson=next(x for x in lessons if x['id']==id)
            lesson.update(chapter=number,chapter_title=title,lesson_order=order)
